(function(){var log=[],x='g';function f(){with({x:'w'}){try{return 1;}finally{log.push(x);}}}log.push(f());for(;;){with({x:'w'}){try{break;}finally{log.push(x);}}}log.push(x);outer:for(var i=0;i<2;i++){with({x:'a'+i}){with({x:'b'+i}){try{continue outer;}finally{log.push(x);}}}}function h(){with({x:'z'}){try{throw 2;}finally{log.push(x);}}}try{h();}catch(e){log.push(e);}return log.join('/');})()
